import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"49、【革】 离下兑上","description":"周易阐真 - 49、【革】 离下兑上","frontmatter":{"title":"49、【革】 离下兑上","description":"周易阐真 - 49、【革】 离下兑上"},"headers":[],"relativePath":"zh/classics/chanzhen/050.md","filePath":"zh/classics/chanzhen/050.md"}'),s={name:"zh/classics/chanzhen/050.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：革，水火相息，二女同居，其志不相得曰革。已日乃孚，革而信之。文明以说，大亨以正。革而当，其悔乃亡。天地革而四时成，汤武革命，顺乎天而应乎人。革之时大矣哉！</p></blockquote><h1 id="_49、【革】-离下兑上" tabindex="-1">49、【革】 离下兑上 <a class="header-anchor" href="#_49、【革】-离下兑上" aria-label="Permalink to “49、【革】 离下兑上”">​</a></h1><p>初九：巩用黄牛之革。</p><p>六二：己日乃革之，征吉，无咎。</p><p>九三：征凶，贞厉。革言三就，有孚。</p><p>九四：悔亡，有孚改命，吉。</p><p>九五：大人虎变，未占有孚。</p><p>上六：君子豹变，小人革面。征凶，居贞吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：泽中有火，革。君子以治历明时。</p><p>革者，更变也。上兑泽，下离火，是泽中有火也。泽本湿，火本燥。湿太过，而有火燥之；燥太过，而有湿润之。泽火一处，湿燥相济，革之象也。</p><p>君子有见于此，知人之立身处世，不能因事制宜、随时迁就者，皆由不明天道变化之理、阴阳进退之节。以是分春夏秋冬、二十四气、七十二候，治而为历，以明五行之运气，各有其时，使人人顺天随时，变革太过之行，归于中正耳。盖天有运行之时，人有当行之道。时有迁移，道有变化。变化之道，即与时偕行之道。与时偕行，进退存亡不失其正，亦一天行矣。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>革者，去而不用之义，所以去旧也。卦德上兑悦，下离明，悦本于明，以明制悦，悦而不得有妄，明而不得有昧，明中出悦，悦中有明，故谓革。卦象兑为西方金，离为南方火，以火炼金，金遇火而生明返阳，火遇金而入库返本，亦革之义。此煅炼阴气之卦，承上困卦而来。困者，险中出悦，所以取坎中真阳以出险也。然能取坎中真阳，而不能复离中真阴，金丹不结，仍不得悦，此明中出悦之道，不可缺也。明中出悦，煅炼阴气之功也。煅炼阴气，是煅炼己之私欲，无我之谓也。</p><p>人为万物之灵，秉天地阴阳五行之正气而生。当有生之初，不识不知，顺帝之则，至善无恶，真性炯炯，虚灵不昧，喜怒哀乐，不着于心，富贵穷通，不动其意，虎兕不能伤，刀兵不能加，水火不能浸，生死不能累，饥只食，寒只衣，无思无虑，德本明也。及至二八，阳极生阴，后天用事，气质之性发，知识之窍开。当斯时也，惟天纵上智之圣人，先天而天弗违，后天而奉天时，能保先天之真，而不为后天所伤。其次中下之人，鲜有不为后天所规弄者。</p><p>自此而后，百忧感其心，万事劳其形，认假为真，弃正入邪，日复一日，年复一年，性相近而习相远，明德有伤，新者积而成旧，净者染而有垢，此旧染之污，所由来也。原其有旧染之污者，皆由有己，一有其己，则道心昧而人心生，明非所明，悦非所悦，顺其所欲，无所不至矣。</p><p>革者，即革其己之不明，以复于明耳。然欲革其己之不明，须要己先能明。己既能明，则信于革，而己之不明可革矣。是以革之道，己日乃孚也。</p><p>日者，明之象；孚者，信之谓。不明不信，能明乃信，明之信之，初念已真，未有不能革己者。是以革有元亨之道也。但革虽有元亨之道，又须革之得正。若是非不分，真假罔辨，一概革之，入于顽空寂灭之学，不正即不利，不利仍是不元亨，惟以正而革，克己复礼，去妄存诚，煅去后天一切滓质，现出先天一灵真性。到此地位，还元返本，浑然天理，纯白无玷，有己之悔可亡矣。是道也，非知之艰，行之维艰，是在人之能信于革耳。</p><p>初九，刚而不明，不能逆革其内，乃顺革于外，如巩用黄牛之革，顾外失内，固执不通。此舍本逐末之革也。</p><p>六二，虚心自处，明于革而先能去其私欲。私欲能去，则无己。无己则有人，有人则以己求人，即能实腹。实腹而己愈明，是以征吉，而且无咎。此虚心求明之革也。</p><p>九三，刚而太过，只知革人，不知革己，虽革事得正，亦有凶属。盖以不能革己，即欲革人，不但人不受我革，且将有言来革我，虽欲不自革而不能。是以革言三就也。三就之革，可信其终于不能革己矣。此自大自尊之革也。</p><p>九四，有刚不用，是以有悔可亡，悔出于不信革己。若信革己，刚即能柔，可以变化气质，而不为阴阳所拘，岂仅有己之悔可亡，方且有改命之吉。此刚以柔用之革也。</p><p>九五，阳刚中正，主宰在内，扶阳抑阴，开生门、闭死户，留人道、塞鬼路，一切客气，自消自化，如虎威常在，不变之变，无容占信其已革矣。此大人用刚有为之革也。</p><p>上六，在革之终。柔而得正，炼己功勤，虚极静笃，如豹不威之变，诚中达外，气质俱化，根尘全消，净倮倮、赤洒洒，形神俱妙，与道合真矣。此君子用柔无为之革也。然用柔无为之革，惟有信心之君子能之，一切不信心之小人，则不能。盖小人者，革面不革心，志念不坚，有始无终，必落空亡而致凶。君子者，永居于贞，志念长久，愈久愈力，终必成道而得吉。此邪正结果之革也。</p><p>六爻俱有革道，是非不等，总以无己为归着。若稍有一点己在，革去而又来，阴气不尽，阳气不纯，古经所谓“七返还丹，在人先须炼己待时”者，正欲其革去一切旧染之污，不使有丝毫之疵，留于方寸之中也。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
